const allowedRoles = ['operator', 'auditor', 'coordinator', 'reviewer'];
const forbidden = ['git_push','merge_main','production_deploy','real_sms','real_calls','secret_changes'];
const body = $json.body;

const missionId = String(body.mission_id ?? '').trim();
const objective = String(body.objective ?? '').trim();
const role = String(body.role ?? 'operator').trim();
const maxIterations = Number(body.max_iterations ?? 0);

function errorResponse(error) {
  return [{ json: { valid: false, status: 'error', error } }];
}

if (!missionId) return errorResponse('missing_mission_id');
if (!objective) return errorResponse('missing_objective');
if (!allowedRoles.includes(role)) return errorResponse('invalid_role');
if (!Number.isInteger(maxIterations) || maxIterations < 1 || maxIterations > 8) {
  return errorResponse('invalid_max_iterations');
}

const objectiveLower = objective.toLowerCase();
for (const f of forbidden) {
  if (objectiveLower.includes(f.replace(/_/g, ' '))) {
    return errorResponse('forbidden_objective');
  }
}

const now = new Date().toISOString();
let missionContext = {};
if (typeof body.mission_context_json === 'string') {
  try { missionContext = JSON.parse(body.mission_context_json); } catch(e) {}
} else if (body.mission_context_json) {
  missionContext = body.mission_context_json;
}

return [{
  json: {
    valid: true,
    mission_id: missionId,
    task_id: String(body.task_id ?? missionId),
    status: 'queued',
    current_role: role,
    next_role: String(body.next_role ?? role),
    iteration: 0,
    max_iterations: maxIterations,
    approval_required: false,
    budget_allowed: true,
    updated_at: now,
    created_at: now,
    mission_context_json: JSON.stringify({
      ...missionContext,
      objective,
      priority: String(body.priority ?? 'normal'),
      role,
      source: 'luna-mission-create',
      created_by: 'Ludovic',
      anti_regression: true,
      guardian_target: true,
      budget_guardrails_enabled: true,
      forbidden_actions: ['git_push','merge_main','production_deploy','real_sms','real_calls','secret_changes']
    })
  }
}];

const response = await this.helpers.httpRequest({
  method: 'POST',
  url: 'http://127.0.0.1:9876/create',
  headers: { 'Content-Type': 'application/json' },
  body: $json,
  json: true,
});
return [{ json: response && Object.keys(response).length ? response : { status: 'error', error: 'empty_store_response' } }];
